-- ============================================================
-- seed-grant-details.sql
-- Real eligibility criteria + specific required documents for all grants.
-- Run in Supabase SQL editor.
-- ============================================================

-- ── SBA / SMALL BUSINESS ─────────────────────────────────────────────────────

UPDATE grants SET
  eligibility_criteria = '["Must have completed a Phase I SBIR award with satisfactory results from the same agency", "Business must have 500 or fewer employees (including affiliates)", "Must be at least 51% owned and controlled by US citizens or permanent residents", "Must be a for-profit US business with principal place of business in the US", "Phase II proposal must address the same technology topic as the Phase I award"]'::jsonb,
  required_documents = '["Phase I Final Report demonstrating technical feasibility", "Technical proposal (20-page limit) including commercialization plan", "Company certifications (SBA Form 1771) confirming size and ownership", "Budget justification with detailed cost breakdown", "Biographical sketches for all key personnel (2-page NIH-style format)", "Letters of intent or MOUs with potential commercial partners (if applicable)"]'::jsonb
WHERE slug = 'sbir-phase-2-grant';

UPDATE grants SET
  eligibility_criteria = '["Business must have 500 or fewer employees (including affiliates)", "Must be at least 51% owned and controlled by US citizens or permanent residents", "Must be a for-profit US small business with principal place of business in the US", "Must have a formal collaboration agreement with a US nonprofit research institution (university, federal lab, or research hospital)", "The research institution must perform at least 30% of the R&D work; the small business must perform at least 40%"]'::jsonb,
  required_documents = '["Technical proposal (20-page limit) describing the innovation and feasibility plan", "Formal research collaboration agreement (MOU or subcontract) with the partner institution", "Budget justification for both the small business and research institution portions", "Biographical sketches for key personnel at both organizations", "Company certifications (SBA Form 1771)", "Partner institution''s 501(c)(3) determination letter or proof of nonprofit status"]'::jsonb
WHERE slug = 'sttr-phase-1-grant';

UPDATE grants SET
  eligibility_criteria = '["Must have completed a Phase I STTR award with satisfactory results", "Business must have 500 or fewer employees (including affiliates)", "Must be at least 51% owned and controlled by US citizens or permanent residents", "Formal collaboration with the same (or a new) qualifying US nonprofit research institution must continue", "The research institution must perform at least 30% of the R&D work throughout Phase II"]'::jsonb,
  required_documents = '["Phase I Final Report", "Technical proposal (20-page limit) with expanded R&D scope and commercialization strategy", "Updated research collaboration agreement with partner institution", "Budget justification for both organizations", "Biographical sketches for all key personnel", "Company certifications (SBA Form 1771)"]'::jsonb
WHERE slug = 'sttr-phase-2-grant';

UPDATE grants SET
  eligibility_criteria = '["Business must have 500 or fewer employees", "Must operate in an underserved or low-income market, rural community, or distressed area", "Must be a for-profit US small business registered in SAM.gov", "Must demonstrate inability to obtain credit on reasonable terms elsewhere", "Must not have any existing SBA loan in default or prior SBA loss", "Personal net worth of owner(s) under $750,000 (excluding primary residence and business assets)"]'::jsonb,
  required_documents = '["SBA Form 1919 (Borrower Information Form)", "SBA Form 413 (Personal Financial Statement) for each owner with 20%+ stake", "Business financial statements: profit & loss (last 2 years) and balance sheet", "Business and personal tax returns (last 3 years)", "Business plan or executive summary including use of funds", "Business licenses, articles of incorporation, and any franchise agreements"]'::jsonb
WHERE slug = 'sba-community-advantage-loans';

UPDATE grants SET
  eligibility_criteria = '["Must be a unit of state or local government, institution of higher education, non-profit organization, or public or private entity", "Project must be located in an economically distressed area (20%+ unemployment, 80% or less of national median income, or special need)", "Must demonstrate matching funds — EDA typically requires a 20-50% match", "Project must create or retain private-sector jobs and leverage private investment", "Must have a current Comprehensive Economic Development Strategy (CEDS) or equivalent"]'::jsonb,
  required_documents = '["EDA investment application (submitted via grants.gov)", "Comprehensive Economic Development Strategy (CEDS) for the region", "Environmental review documentation (NEPA compliance)", "Evidence of matching funds (bank letters, local government commitments)", "Project cost estimates from licensed engineers or architects", "Letters of support from state and local officials", "SF-424 (Application for Federal Assistance)"]'::jsonb
WHERE slug = 'eda-economic-development-grants';

UPDATE grants SET
  eligibility_criteria = '["Must be a certified Community Development Financial Institution (CDFI) or applying for CDFI certification", "Must serve a defined low-income target market", "Must demonstrate that requested technical assistance directly builds capacity to serve underserved communities", "Must not have received a CDFI Program Award in the prior funding round (for some competitions)", "Organization must have been in operation for at least 1 year"]'::jsonb,
  required_documents = '["CDFI Fund online application (through AMIS portal)", "CDFI certification documentation or certification application", "Audited financial statements (most recent 2 years)", "Narrative describing target market and community impact", "Board resolution authorizing the application", "IRS determination letter confirming tax-exempt status (if applicable)"]'::jsonb
WHERE slug = 'cdfi-technical-assistance-grants';

UPDATE grants SET
  eligibility_criteria = '["Must be a for-profit US small business with 500 or fewer employees", "Must be registered and in good standing in SAM.gov", "Must demonstrate a need for export assistance (new or expanding export activity)", "Must be headquartered in a participating state (program operates through state trade agencies)", "Must not be exporting products or services that are prohibited under US export laws"]'::jsonb,
  required_documents = '["STEP application submitted through your state trade office", "Business plan or export plan outlining target markets and strategy", "Proof of small business status (employee count, revenue documentation)", "SAM.gov registration confirmation (UEI number)", "Tax returns or financial statements showing US-based operations", "Itemized budget for export activities to be funded"]'::jsonb
WHERE slug = 'step-export-assistance';

UPDATE grants SET
  eligibility_criteria = '["Business must be at least 51% owned and controlled by socially and economically disadvantaged individuals (African Americans, Hispanic Americans, Asian Americans, Native Americans, and others who have experienced racial or ethnic prejudice)", "Owner must have personal net worth under $850,000 (excluding primary residence and 401k)", "Owner''s adjusted gross income must average under $400,000 for the prior 3 years", "Business must have been in operation for at least 2 years", "Business must not exceed SBA size standards for its primary NAICS code"]'::jsonb,
  required_documents = '["SBA Form 1010C (Application for 8(a) Business Development)", "Personal financial statement (SBA Form 413) for each disadvantaged owner", "Personal tax returns (last 3 years) for each disadvantaged owner", "Business tax returns (last 3 years)", "Narrative statement of social disadvantage with supporting documentation", "Articles of incorporation, LLC operating agreement, or partnership agreement showing ownership percentages", "Business licenses and any professional certifications"]'::jsonb
WHERE slug = 'sba-8a-business-development';

UPDATE grants SET
  eligibility_criteria = '["Must be in a designated Opportunity Zone census tract (look up your address at irs.gov/opportunity-zones)", "Investment must be made through a Qualified Opportunity Fund (QOF) — you cannot invest directly", "Must invest capital gains proceeds within 180 days of the gain realization", "Business in the zone must derive at least 50% of gross income from active conduct in the zone", "At least 70% of tangible business property must be Opportunity Zone Business Property"]'::jsonb,
  required_documents = '["IRS Form 8997 (Initial and Annual Statement of Qualified Opportunity Fund Investments)", "IRS Form 8949 or Schedule D showing original capital gain being deferred", "QOF''s Form 8996 (Qualified Opportunity Fund) with annual self-certification", "Investment documentation: subscription agreement and proof of investment in the QOF", "Business plan or property development plan for the Opportunity Zone investment", "Proof that the census tract is an Opportunity Zone (Treasury census tract list)"]'::jsonb
WHERE slug = 'opportunity-zone-business-investment';

UPDATE grants SET
  eligibility_criteria = '["Business must be located in a rural area (population under 50,000 per USDA definition)", "Must have 10 or fewer full-time employees at time of application", "Must be a for-profit business or cooperative", "Must demonstrate inability to obtain credit on reasonable terms from conventional sources", "Must have been in business at least 1 year or demonstrate relevant industry experience"]'::jsonb,
  required_documents = '["USDA Rural Development loan/grant application (RD Form 4279-1)", "Business plan with 3-year financial projections", "Personal financial statement for each owner with 20%+ stake", "Business and personal tax returns (last 3 years)", "Proof of rural location (USDA Rural Development eligibility map screenshot)", "Any existing business licenses, permits, and incorporation documents"]'::jsonb
WHERE slug = 'rural-microentrepreneur-assistance';

UPDATE grants SET
  eligibility_criteria = '["Must be a member of a federally recognized American Indian tribe or Alaska Native village, or be enrolled in a BIA-recognized tribal entity", "Must be a US citizen", "The business development project must benefit the tribal community and be located on or near tribal land", "Project must not duplicate services available from other federal programs", "Tribal government or tribal organization must endorse or be the applicant"]'::jsonb,
  required_documents = '["Tribal resolution authorizing the application and designating a tribal representative", "Business plan or feasibility study for the proposed development project", "Proof of tribal enrollment for principal owner(s)", "Financial statements showing the tribe''s or organization''s current fiscal standing", "Letters of support from tribal council or tribal enterprise leadership", "Any environmental or cultural resource assessments if land use is involved"]'::jsonb
WHERE slug = 'native-american-business-development';

UPDATE grants SET
  eligibility_criteria = '["Business must have 500 or fewer employees (DOE SBIR uses this SBA standard)", "Must be at least 51% owned and controlled by US citizens or permanent residents", "Must be a for-profit business with principal place of business in the US", "Proposed research must address a specific DOE SBIR/STTR topic area announced in the current solicitation", "Principal Investigator must be primarily employed by the small business (more than 50% effort)"]'::jsonb,
  required_documents = '["Technical volume (Phase I: 25 pages max) addressing the specific DOE topic", "Company certifications (SBA Form 1771)", "Key personnel biographical sketches", "Budget and budget justification using DOE SF-424 forms", "Facilities and equipment description", "Letters of intent from any collaborative partners or future customers"]'::jsonb
WHERE slug = 'doe-small-business-clean-energy';

UPDATE grants SET
  eligibility_criteria = '["Must be a US business that exports or seeks to export US goods and services", "Must be in an export-related industry (manufacturing, agriculture, services with US content)", "Business must have a viable export plan or existing export sales", "Must meet SBA size standards for small business designation", "Transactions must involve US-made goods or services (minimum 50% US content for products)"]'::jsonb,
  required_documents = '["EXIM Bank application (online at exim.gov)", "Export credit insurance application or working capital application form", "Business and personal financial statements (last 2 years)", "Export sales history or projected export sales documentation", "Purchase orders or contracts from foreign buyers (if available)", "SAM.gov registration and UEI number"]'::jsonb
WHERE slug = 'exim-small-business-program';

UPDATE grants SET
  eligibility_criteria = '["Must be a small business as defined by SBA size standards", "Must operate in an industry with environmental regulations (manufacturing, dry cleaning, automotive, printing, agriculture, etc.)", "Must be a US business subject to federal, state, or local environmental regulations", "Program is open to businesses regardless of prior compliance history for most services", "Some states restrict assistance to businesses with no current enforcement actions"]'::jsonb,
  required_documents = '["Request for assistance (free, typically a phone call or online form to your state SBEAP)", "Description of business operations and environmental concerns", "Any recent inspection reports or agency correspondence (if applicable)", "Business registration or license showing state of operation"]'::jsonb
WHERE slug = 'small-business-environmental-assistance';

UPDATE grants SET
  eligibility_criteria = '["Must be a for-profit US business with a primary place of business in a designated HUBZone", "Must be at least 51% owned and controlled by US citizens, a Community Development Corporation, an agricultural cooperative, or a Native American tribal entity", "At least 35% of the company''s employees must reside in a HUBZone", "Must meet SBA size standards for small business", "Must maintain HUBZone compliance continuously to keep certification"]'::jsonb,
  required_documents = '["SBA HUBZone application (online at certify.sba.gov)", "Proof of business location in a HUBZone (lease agreement, utility bill, or property deed for principal office)", "Articles of incorporation, LLC operating agreement, or partnership agreement showing ownership", "List of all employees with home addresses to verify 35% HUBZone residency requirement", "Payroll records confirming employee residency and employment status", "SAM.gov registration"]'::jsonb
WHERE slug = 'hubzone-program';

UPDATE grants SET
  eligibility_criteria = '["Firm must be owned by socially and economically disadvantaged individuals — women (51%+), minorities (51%+), or individuals with disabilities (51%+)", "Must be a for-profit firm with a primary business in transportation-related services or construction", "Must be certified as a Disadvantaged Business Enterprise (DBE) by your state DOT", "Firm''s average annual gross receipts must not exceed $26.29 million (3-year average)", "Owner''s personal net worth must not exceed $1.32 million (excluding primary residence and business equity)"]'::jsonb,
  required_documents = '["DBE certification application (submitted to your state DOT — each state has its own form)", "Personal net worth statement (PNW Statement) for each socially disadvantaged owner", "Personal and business tax returns (last 3 years)", "Business organizational documents (articles of incorporation, operating agreement) showing ownership percentages", "Social disadvantage narrative explaining how the owner has experienced racial or ethnic prejudice", "Professional licenses or certifications relevant to the transportation services offered"]'::jsonb
WHERE slug = 'dot-disadvantaged-business-enterprise';

UPDATE grants SET
  eligibility_criteria = '["Must be a US manufacturer with fewer than 500 employees", "Must be a domestic US manufacturer (primary manufacturing activity in the US)", "Must be willing to engage with an MEP Center for services (not purely a grant — it is a subsidized consulting program)", "Cost-share is required: manufacturers typically pay 30-50% of service costs", "Priority given to small and medium manufacturers facing competitiveness, supply chain, or workforce challenges"]'::jsonb,
  required_documents = '["Contact your regional MEP Center (find at nist.gov/mep/centers) — no formal grant application", "Business assessment questionnaire (completed with MEP advisor)", "Financial statements or tax returns may be requested to confirm size eligibility", "Description of manufacturing operations, products, and markets served"]'::jsonb
WHERE slug = 'manufacturing-extension-partnership';

UPDATE grants SET
  eligibility_criteria = '["Applicant must be a US industry, educational institution, workforce organization, or economic development entity", "Must serve workers in industries at risk of displacement or with significant skills gaps", "Project must involve a sector partnership of multiple employers in a single industry", "Must provide training leading to industry-recognized credentials in in-demand occupations", "Applicants must demonstrate employer commitment and partnerships in the target sector"]'::jsonb,
  required_documents = '["EDA Good Jobs Challenge application (via grants.gov during open competition)", "SF-424 (Application for Federal Assistance)", "Project narrative describing the industry sector partnership and training plan", "Evidence of employer commitments and letters of support", "Budget and budget narrative with EDA cost-share documentation", "Resumes of key project personnel"]'::jsonb
WHERE slug = 'good-jobs-challenge-grant';

UPDATE grants SET
  eligibility_criteria = '["Must be a private, nonprofit organization, state/local government, or tribal organization", "Must operate as a navigator hub connecting small businesses to SBA resources", "Must demonstrate existing network and track record of serving underserved small businesses", "Proposed navigator program must prioritize underserved small business communities (rural, minority-owned, veteran-owned, women-owned)", "Must have organizational capacity to administer a federal subaward"]'::jsonb,
  required_documents = '["SBA Community Navigator application (via grants.gov)", "SF-424 (Application for Federal Assistance)", "Project narrative describing existing network, target population, and outreach plan", "Audited financial statements (last 2 years)", "Organizational chart and key staff resumes", "Letters of support from community partners and local SBA district office"]'::jsonb
WHERE slug = 'community-navigator-pilot';

UPDATE grants SET
  eligibility_criteria = '["Must be an existing SBA 7(a) or 504 borrower with a loan in good standing at the time of COVID-19 emergency (program was pandemic-specific)", "Loan must have been approved before September 27, 2020", "Business must have a North American Industry Classification System (NAICS) code beginning with 61, 71, 72, 213, 315, 448, 451, 481, 485, 487, 511, 512, 515, 532, or 812 for 8 months of relief", "All other eligible borrowers qualify for 3 months of relief", "This program has concluded — contact SBA for current relief options"]'::jsonb,
  required_documents = '["SBA loan account number (relief was applied automatically — no application required for most borrowers)", "SBA lender confirmation of loan status", "Contact your SBA lender or call 1-800-659-2955 for current status"]'::jsonb
WHERE slug = 'sba-small-business-debt-relief';

UPDATE grants SET
  eligibility_criteria = '["Must be a US business with up to 15,000 employees or up to $5 billion in 2019 annual revenues (for profit businesses)", "Nonprofit organizations with up to 15,000 employees also qualify", "Business must have been in good financial standing before March 13, 2020 (program was pandemic-era)", "Business must commit to making reasonable efforts to maintain payroll and retain employees", "This program concluded in January 2021 — it is no longer accepting new applications"]'::jsonb,
  required_documents = '["This program is closed. Contact the Federal Reserve or your lender for current small business lending options.", "For historical reference: SF-424, borrower certifications, 2019 financial statements, and tax returns were required"]'::jsonb
WHERE slug = 'main-street-lending-program';

UPDATE grants SET
  eligibility_criteria = '["Must be applying to become a CDFI (new applicants) or already be a certified CDFI (current CDFIs seeking expansion capital)", "Must serve a defined low-income target market with a primary mission of community development", "Must maintain accountability to low-income community members through governance structure", "Must provide development services in conjunction with financial products", "Nonprofit CDFIs must have audited financials; for-profit CDFIs must have reviewed financials at minimum"]'::jsonb,
  required_documents = '["CDFI Fund AMIS (Awards Management Information System) application portal submission", "CDFI certification letter (or CDFI certification application if applying for first time)", "Audited financial statements (last 2 fiscal years)", "Strategic plan demonstrating community impact and sustainability", "Board resolution authorizing the application", "Portfolio data showing current lending/investing activity in the target market"]'::jsonb
WHERE slug = 'distressed-capital-access-program';

-- ── AGRICULTURAL ─────────────────────────────────────────────────────────────

UPDATE grants SET
  eligibility_criteria = '["Must be an independent agricultural producer, farmer, rancher, fisher, or agricultural cooperative", "Must produce or plan to produce a value-added product from an agricultural commodity", "For Planning Grants: must demonstrate need to assess feasibility of a value-added enterprise", "For Working Capital Grants: must already have a business plan and demonstrate the value-added activity is operational or near-operational", "Farmer must have gross sales from farming below $1 million/year for Simplification category; all agricultural producers qualify for other categories"]'::jsonb,
  required_documents = '["USDA Rural Development VAPG application (RD Form 1940-20)", "Business plan or feasibility study (required for Working Capital grants)", "3 years of farm tax returns (Schedule F or Form 1120) showing agricultural production income", "Documentation proving you are the producer of the raw agricultural commodity", "Budget and cost breakdown for proposed value-added activities", "Letters of support or contracts from buyers or distributors (if available)"]'::jsonb
WHERE slug = 'usda-value-added-producer-grant';

UPDATE grants SET
  eligibility_criteria = '["Must be a farmer, rancher, or agricultural producer; researcher at a US institution; or agricultural educator or extension specialist (eligibility varies by SARE program — Farmer, Professional Development, or Research & Education)", "For Farmer/Rancher grants: project must test a sustainable agriculture practice on your own farm", "For Professional Development grants: must be an extension agent or agricultural educator", "For Research & Education grants: must be affiliated with a university, nonprofit, or SARE host institution", "Projects must address sustainability goals in economics, environment, or social equity"]'::jsonb,
  required_documents = '["SARE grant application submitted online at sare.org (application cycle and forms vary by region and grant type)", "Project proposal describing the sustainable practice to be tested and expected outcomes", "Budget with cost justification (cost-share encouraged)", "Resume or CV for principal investigator", "For research grants: institutional sign-off from university or organizational administrator", "References or letters of support (required for some grant types)"]'::jsonb
WHERE slug = 'sare-sustainable-agriculture';

UPDATE grants SET
  eligibility_criteria = '["Must have not operated a farm or ranch for more than 10 consecutive years as a substantial operator (beginning farmer definition)", "Applicant organizations must design programs specifically serving beginning farmers and ranchers", "Projects must address education, mentoring, training, or outreach for beginning farmers", "Priority given to projects serving socially disadvantaged, veteran, or limited-resource beginning farmers", "Applicants must be collaborative partnerships of at least 3 entities (government, nonprofit, educational institution)"]'::jsonb,
  required_documents = '["NIFA grant application submitted via grants.gov (CFDA 10.311)", "Project narrative (25-page limit) describing the beginning farmer training program", "SF-424 (Application for Federal Assistance) and SF-424A (Budget Information)", "Documentation of collaborative partnership agreements with all partner organizations", "Resumes of key project personnel", "Letters of commitment from cooperating organizations"]'::jsonb
WHERE slug = 'beginning-farmer-rancher-development';

UPDATE grants SET
  eligibility_criteria = '["Must be an agricultural producer (farmer, rancher, forest landowner, or tribe) with a history of farming operations", "Must have an eligible conservation practice need identified in the EQIP application", "Must control the land where practices will be applied (own, lease, or have written permission)", "AGI (adjusted gross income) from non-farm sources must not exceed $900,000/year (3-year average)", "Not required: prior EQIP participation, but the land must not already have the practice fully funded by another program"]'::jsonb,
  required_documents = '["EQIP application submitted at your local USDA Service Center (NRCS Form CPA-1200)", "FSA farm number and tract number for the land where practices will be applied", "Conservation plan developed with NRCS staff", "Most recent 3 years of tax returns showing AGI from non-farm sources (for compliance screening)", "Lease agreement or landowner permission letter if you do not own the land", "AD-1026 (Highly Erodible Land Conservation and Wetland Conservation Certification)"]'::jsonb
WHERE slug = 'eqip-environmental-quality-incentives';

UPDATE grants SET
  eligibility_criteria = '["Must be an agricultural producer already operating on eligible agricultural land", "Land must be covered by an active EQIP contract or otherwise qualify under NRCS conservation criteria", "AGI from non-farm sources must not exceed $900,000/year (3-year average)", "Must agree to a 5-year stewardship contract covering conservation performance on the entire operation", "Application is scored — farms with higher existing conservation performance and greater improvement potential receive higher rankings"]'::jsonb,
  required_documents = '["CSP application submitted at your local USDA Service Center (NRCS Form CPA-1200)", "FSA farm number showing enrolled acreage and land tracts", "Conservation Performance Measurement System (CPMS) self-assessment (completed with NRCS staff)", "Documentation of existing conservation activities and their implementation dates", "AD-1026 (Highly Erodible Land Conservation and Wetland Conservation Certification)", "Most recent 3 years of tax returns for AGI determination"]'::jsonb
WHERE slug = 'conservation-stewardship-program';

UPDATE grants SET
  eligibility_criteria = '["Must be a farmer, rancher, or cooperative with documented need for on-farm storage or handling facilities", "Must have an FSA farm number showing production history for the commodity to be stored", "Net worth must not exceed $1.5 million for owners", "Proposed facility must meet USDA minimum structural standards", "Not eligible for land purchase, home improvements, or non-agricultural equipment"]'::jsonb,
  required_documents = '["FSFL application (FSA Form 1357) submitted at your local FSA county office", "Construction quote or invoice from a licensed contractor for the proposed facility", "Proof of adequate production history (farm records or FSA production history report)", "Appraisal of existing facilities and land (for loans over $50,000)", "Financial statements (balance sheet and income statement)", "Environmental review documentation (FSA Form AD-1006)"]'::jsonb
WHERE slug = 'farm-storage-facility-loan';

UPDATE grants SET
  eligibility_criteria = '["Applicant must be a US State Department of Agriculture or its designee", "Proposed projects must benefit specialty crops — fruits, vegetables, tree nuts, dried fruits, horticulture, and nursery crops (not field crops or livestock)", "Projects must enhance the competitiveness of specialty crops", "State SCBGP applications must be submitted to USDA AMS; states then award subgrants to producers, processors, and organizations", "Individual growers apply through their State Department of Agriculture, not directly to USDA"]'::jsonb,
  required_documents = '["Application to your State Department of Agriculture (each state has its own process and timeline)", "Project narrative describing how the project benefits specialty crops in the state", "Budget and budget narrative", "Evidence of specialty crop status for the target commodity", "Letters of support from industry organizations or state agriculture officials (varies by state)"]'::jsonb
WHERE slug = 'specialty-crop-block-grant';

UPDATE grants SET
  eligibility_criteria = '["Must be a US land-grant university, non-land-grant college of agriculture, USDA agency, or other public or private research institution", "Research must focus on organic agriculture production, handling, marketing, or policy", "Principal Investigator must have a PhD in a relevant agricultural or life science field", "Project must be collaborative — integrated projects combining research, education, and extension are prioritized", "Must be submitted during an open OREI funding opportunity on grants.gov"]'::jsonb,
  required_documents = '["NIFA OREI application via grants.gov (CFDA 10.307)", "Project narrative (15-25 pages depending on grant type) including research objectives, methods, and milestones", "SF-424 (Application for Federal Assistance) and SF-424A (Budget Information)", "Curriculum Vitae (CV) for the Principal Investigator and all co-investigators", "Letters of collaboration from partner organizations", "Institutional authorization from Sponsored Research Office"]'::jsonb
WHERE slug = 'organic-agriculture-research-initiative';

UPDATE grants SET
  eligibility_criteria = '["Must be a livestock, honeybee, or farm-raised fish producer with documented losses due to drought, wildfire, or other eligible disasters during the program year", "Must have been in the business of livestock production before the disaster occurrence", "Grazing losses must occur on eligible grazing land (must have a grazing plan)", "Normal grazing period must be reduced by at least 30% due to the qualifying natural disaster", "Must have and maintain livestock through the end of the program year"]'::jsonb,
  required_documents = '["LFP application (FSA Form FSA-848) filed at your local FSA county office within 30 days of the end of the applicable calendar year", "Records showing the number, type, and kind of eligible livestock", "Lease agreements for grazing land and documentation of normal grazing period", "FSA farm number and records of livestock inventories", "USDA drought monitor confirmation or other documentation of qualifying disaster", "Verification of land control (deed, lease, or written permission)"]'::jsonb
WHERE slug = 'livestock-forage-disaster-program';

UPDATE grants SET
  eligibility_criteria = '["Must be a commercial producer of livestock, honeybees, farm-raised fish, or other animals suffering losses due to an eligible adverse weather event or animal disease", "Losses must have occurred in the current or prior year and must be documented", "Must have an FSA farm number registered at the time of the loss", "Must be a US citizen, resident alien, partnership, corporation, estate, or trust", "Losses from diseases, predation, extreme cold/heat, floods, and similar events are eligible"]'::jsonb,
  required_documents = '["ELAP application (FSA Form 574) filed at your local FSA county office within 30 days of the end of the calendar year in which losses occurred", "Detailed list of livestock, honeybee colonies, or fish lost with dates of loss", "Veterinary records, mortality records, or other documentation proving the cause and extent of loss", "Receipts, purchase records, or appraisals showing the value of lost animals", "FSA farm number registration printout"]'::jsonb
WHERE slug = 'emergency-livestock-assistance-program';

UPDATE grants SET
  eligibility_criteria = '["Must be a commercial producer of non-insurable crops (crops not covered by USDA crop insurance)", "Crop must be produced in an area where crop insurance is not available or impractical", "Must have a FSA farm number and a filed acreage report before the start of the planting period", "Losses must meet a 50% loss threshold at less than 55% of the established price", "Coverage must be purchased before planting (not after a loss occurs)"]'::jsonb,
  required_documents = '["NAP application for coverage (FSA-840 form) submitted before the application closing date at your local FSA county office", "Acreage report (FSA-578) showing planted acreage by crop and field", "Production records for at least 5 years (or the maximum available) to establish the approved yield", "Notice of Loss (FSA-576) filed within 15 days of a natural disaster causing a potential loss", "Service fee payment at time of application ($325 per crop, $825 per farm maximum)"]'::jsonb
WHERE slug = 'noninsured-crop-disaster-assistance';

UPDATE grants SET
  eligibility_criteria = '["Must be an agricultural landowner, operator, or Indian tribe with eligible agricultural land or wetland", "For Agricultural Land Easements (ALE): land must be prime or unique farmland threatened by conversion to non-agricultural uses", "For Wetland Reserve Easements (WRE): land must be restorable wetland that was previously farmed", "Landowner must agree to perpetual or 30-year easement terms restricting development", "Entity partners (land trusts, state agencies) apply to NRCS on behalf of willing landowners"]'::jsonb,
  required_documents = '["ACEP application submitted by an eligible partner entity (land trust, state/local government) to your state NRCS office", "Legal description and map of the property (survey or deed)", "Appraisal of the land (conducted by NRCS-approved appraiser)", "Title search showing clear title", "Conservation plan or restoration plan for the easement area", "Signed easement deed (NRCS-approved form) after funding is awarded"]'::jsonb
WHERE slug = 'agricultural-conservation-easement-program';

UPDATE grants SET
  eligibility_criteria = '["Must be a producer, group of producers, farmer cooperative, or regional food business entity", "Must propose a project that develops, expands, or coordinates a local or regional food system", "Project must demonstrate meaningful connections between producers and markets (schools, hospitals, food hubs, retail)", "Letters of commitment from supply chain partners (buyers, producers) are required", "Priority given to projects that strengthen supply chains for locally and regionally produced agricultural products"]'::jsonb,
  required_documents = '["RFSP application (via grants.gov during open solicitation period)", "SF-424 (Application for Federal Assistance)", "Project narrative (10-page limit) describing food system partnerships and outcomes", "Letters of commitment from all supply chain partners", "Budget and budget justification", "Evidence of past work in local food systems (annual reports, case studies)"]'::jsonb
WHERE slug = 'regional-food-system-partnerships';

UPDATE grants SET
