  required_documents = '["SF-424 R&R Application form (submitted via NIH ASSIST, Grants.gov, or institutional system)", "Research Strategy (12 pages for most R01s: Significance, Innovation, Approach)", "NIH Biosketch for PI and all key personnel (5-page limit per person)", "Budget (modular up to $250,000 direct costs/year; detailed budget for larger amounts)", "Facilities & Other Resources statement", "Equipment description", "Human Subjects or Vertebrate Animals sections (if applicable)", "Letters of support from collaborators and institutional officials"]'::jsonb
WHERE slug = 'nih-r01-research-grant';

