  required_documents = '["Javits Fellowship application (submitted via the Department of Education''s application system)", "FAFSA (for financial need determination)", "Official transcripts from undergraduate and graduate institutions", "Dissertation proposal or research statement (10-page limit)", "Three letters of recommendation from graduate faculty", "Writing sample demonstrating scholarly ability (20-30 pages)"]'::jsonb
WHERE slug = 'javits-fellowship';

UPDATE grants SET
  eligibility_criteria = '["Must be a US citizen or permanent resident (program was historically for US students only)", "Must be pursuing or planning to pursue teacher preparation or teaching career at the K-12 level", "Must demonstrate financial need (FAFSA-required)", "This program is no longer actively funded by Congress as of recent budget cycles — check studentaid.gov for current status", "If active: must attend a state-designated teacher shortage area school upon completion"]'::jsonb,
  required_documents = '["FAFSA filed at studentaid.gov", "Application submitted through the participating state or institution", "Intent to teach certification", "Official transcripts", "Financial need documentation from financial aid office"]'::jsonb
WHERE slug = 'paul-douglas-teacher-scholarship';

UPDATE grants SET
  eligibility_criteria = '["Must be an American Indian or Alaska Native who is an enrolled member of a federally recognized tribe or a first-generation descendant of an enrolled member", "Must be a US citizen", "Must be accepted or enrolled full-time in an accredited health professions program (medicine, nursing, dentistry, pharmacy, public health, physician assistant, etc.)", "Must demonstrate financial need", "Must commit to a 2-year service obligation at an IHS/tribal/urban Indian health facility for each year of scholarship support received"]'::jsonb,
  required_documents = '["IHS Scholarship application (via online portal at ihs.gov/scholarship)", "Proof of tribal enrollment: tribal enrollment card, Certificate of Degree of Indian Blood (CDIB), or letter from tribal enrollment office", "Official transcripts from all institutions attended", "Official letter of acceptance or enrollment from an accredited health professions school", "FAFSA Student Aid Report (for financial need determination)", "Personal statement describing commitment to serving Indian communities", "Two letters of recommendation"]'::jsonb
WHERE slug = 'ihs-scholarship';

-- ── INDIVIDUAL ASSISTANCE (also in benefits but may appear as grants) ─────────

UPDATE grants SET
  eligibility_criteria = '["Must have a medically determinable physical or mental impairment that prevents substantial gainful activity (SGA — $1,550/month in 2024)", "Disability must have lasted or be expected to last at least 12 months, or be expected to result in death", "Must have enough Social Security work credits (generally 40 credits, 20 earned in last 10 years — varies by age)", "Must not be performing substantial gainful activity at time of application", "Prior Medicare enrollment is not required — Medicare eligibility begins 24 months after SSDI benefit start"]'::jsonb,
  required_documents = '["SSA Form SSA-16 (Application for Disability Insurance Benefits) — apply online at ssa.gov or call 1-800-772-1213", "Medical records documenting your condition from all treating physicians (SSA will request these with your authorization)", "SSA-827 (Authorization to Disclose Information to the Social Security Administration) signed to release medical records", "Work history: employer names, addresses, dates, and job descriptions for the past 15 years", "W-2s or self-employment tax returns for the past 5 years", "Social Security card and government-issued photo ID"]'::jsonb
WHERE slug = 'social-security-disability-insurance';

UPDATE grants SET
  eligibility_criteria = '["Must have limited income: earnings below $1,971/month for an individual (2024 substantial gainful activity threshold does not directly apply — SSI uses a different income formula)", "Must have limited resources: no more than $2,000 in countable assets for an individual ($3,000 for a couple)", "Must be aged 65 or older, OR be blind (visual acuity 20/200 or less), OR have a qualifying disability expected to last at least 12 months", "Must be a US citizen or qualifying non-citizen (certain immigration statuses qualify)", "Must reside in the US, the Northern Mariana Islands, or, in some cases, outside the US under specific conditions"]'::jsonb,
  required_documents = '["SSA Form SSA-8000 (Application for Supplemental Security Income) — apply online at ssa.gov, in person, or by phone at 1-800-772-1213", "Social Security card and government-issued photo ID", "Birth certificate or other proof of age", "Proof of all income sources: recent pay stubs, award letters for any Social Security benefits, bank statements", "Proof of resources: bank statements (last 3 months), investment account statements, property deeds", "Citizenship documentation or immigration papers (if applicable)", "Medical records if applying on the basis of disability (SSA will also request these)"]'::jsonb
WHERE slug = 'supplemental-security-income';

UPDATE grants SET
  eligibility_criteria = '["Must be a family with children under 18 (or 19 if in school) or a pregnant woman", "Family income must be below the state-set TANF limit (varies widely — many states set it at 30-50% of the federal poverty level)", "Must be a US citizen or qualifying non-citizen with eligible immigration status", "Adult recipients must participate in work activities unless exempt (caring for young child, disability, domestic violence)", "Maximum lifetime limit of 60 months of federally-funded TANF cash benefits"]'::jsonb,
  required_documents = '["TANF application at your state or county Department of Social Services (each state has its own form and name — search ''[State] cash assistance application'')", "Birth certificates for all children in the household", "Proof of identity and residency: government-issued ID and utility bill or lease", "Social Security cards for all household members", "Proof of income: recent pay stubs, child support orders, or documentation of no income", "Proof of pregnancy (if applying on that basis): letter from OB or midwife"]'::jsonb
WHERE slug = 'tanf-cash-assistance';

UPDATE grants SET
  eligibility_criteria = '["Family income must be at or below 100% of the Federal Poverty Level (some programs enroll up to 130%)", "Child must be under 5 years old (Head Start); Early Head Start serves ages 0-3 and pregnant women", "Children in foster care are automatically eligible regardless of income", "Children with disabilities may be enrolled up to the program''s 10% disability enrollment threshold", "Families must reside in the service area of a local Head Start program (find at eclkc.ohs.acf.hhs.gov/center-locator)"]'::jsonb,
  required_documents = '["Head Start enrollment application submitted directly to a local Head Start program (not the federal government)", "Proof of household income: pay stubs, tax returns, or benefit award letters (SNAP, TANF, SSI)", "Child''s birth certificate", "Child''s health and immunization records (or plan to obtain them)", "Proof of address: utility bill, lease, or government mail showing current residence", "Documentation of any disabilities or special needs (if applicable, for disability enrollment priority)"]'::jsonb
WHERE slug = 'head-start-program';

UPDATE grants SET
  eligibility_criteria = '["Must be a child under 13 years old (or under 19 with a qualifying disability or who cannot care for themselves)", "Parent or guardian must be working, attending school, or participating in a job training program", "Family income typically must be at or below 85% of state median income (varies by state)", "Family must be unable to afford childcare without assistance", "Child must be a US citizen or qualifying non-citizen (immigration status requirements vary by state)"]'::jsonb,
  required_documents = '["CCDF application at your state lead agency (typically the state child care or human services department — each state has its own form)", "Proof of income: pay stubs (last 30 days), employer letter, or benefit award letters for all household income", "Proof of work, school enrollment, or job training activity: employer letter with hours worked, school enrollment verification", "Child''s birth certificate", "Proof of child care need: enrollment letter or contract from the licensed child care provider", "Social Security numbers for parent(s) and child(ren)"]'::jsonb
WHERE slug = 'child-care-development-fund';

UPDATE grants SET
  eligibility_criteria = '["Must be pregnant, postpartum (up to 6 months for non-breastfeeding; 12 months for breastfeeding mothers), an infant under 1 year old, a child under 5 years old, or a woman with an infant or child under 5", "Must meet income guidelines (at or below 185% of Federal Poverty Level — currently $26,973/year for 1 person in 2024)", "Must have a nutritional risk determined by a health professional (iron deficiency, low weight-for-height, dietary risk, etc.)", "Must reside in a state or territory with a WIC program — available in all 50 states, DC, and 5 territories", "Participants receiving Medicaid, SNAP, or TANF are automatically income-eligible for WIC"]'::jsonb,
