WHERE slug = 'wic-nutrition-program';

UPDATE grants SET
  eligibility_criteria = '["Household income must be at or below 130% of the Federal Poverty Level ($20,678/year for a family of 2 in 2024) for most households", "Must be a US citizen, US national, or qualifying non-citizen (lawful permanent resident, refugee, asylee, etc.)", "Must reside in the state where you are applying", "Households receiving TANF, SSI, or General Assistance are often categorically eligible without income verification", "Resources (savings, checking) generally not counted for most households — resource limits apply only to specific households with an elderly or disabled member"]'::jsonb,
  required_documents = '["SNAP application at your state or county Department of Social Services (apply online, in person, or by mail — search ''[State] SNAP application'' or visit benefits.gov)", "Proof of identity: driver''s license, state ID, passport, or Social Security card", "Proof of residency: utility bill, lease, or official mail showing current address", "Proof of all household income: pay stubs (last 30 days), employer letters, Social Security award letters, child support orders", "Social Security numbers for all household members (or documentation explaining why an SSN is unavailable)"]'::jsonb
WHERE slug = 'snap-benefits';

UPDATE grants SET
  eligibility_criteria = '["Must own and occupy the home as primary residence", "Property must be located in a rural area eligible for USDA Rural Development programs", "Income must be at or below 50% of the Area Median Income (AMI) for the area for Section 504 grants (homeowners aged 62 and older with income at or below 50% AMI)", "Must be unable to obtain affordable credit elsewhere", "Property must need repairs to remove health or safety hazards or to make the home accessible for people with disabilities", "Grant component (up to $10,000): applicant must be 62 or older and unable to repay a loan"]'::jsonb,
  required_documents = '["USDA Rural Development application (Form RD 410-4, Uniform Residential Loan Application) at your local USDA Rural Development office", "Proof of ownership: deed or land contract", "Most recent 2 years of federal tax returns and current income documentation (pay stubs, Social Security award letters)", "Proof of age for grant applicants (birth certificate or government ID)", "USDA Rural Development eligibility map confirmation of property location (eligibility.sc.egov.usda.gov)", "List of needed repairs with cost estimates from a licensed contractor"]'::jsonb
