UPDATE grants SET
  eligibility_criteria = '["Must be a renter who has experienced financial hardship due to COVID-19 or other qualifying event (program is COVID-era — current availability varies by state)", "Household income must be at or below 80% of Area Median Income", "Must be at risk of homelessness or housing instability — past-due rent, eviction notice, or unsafe/unhealthy housing", "Must not have already received rental assistance covering the same period from another program", "US citizenship is not required — applicants must provide attestation of eligibility"]'::jsonb,
  required_documents = '["Application to your local or state Emergency Rental Assistance program (find at home.treasury.gov/policy-issues/homeowner-assistance-fund and your state/county ERA program website)", "Lease or rental agreement showing landlord contact information and monthly rent amount", "Proof of income: pay stubs, tax return, unemployment benefit statements, or written self-attestation of income", "Evidence of financial hardship: layoff notice, medical bills, unemployment documentation, or written self-attestation", "Landlord cooperation: most programs require landlord to participate and provide banking information for direct payment", "Government-issued ID for adult household members"]'::jsonb
