-- ── FEDERAL PELL GRANT (may be in grants table) ──────────────────────────────

UPDATE grants SET
  eligibility_criteria = '["Must demonstrate exceptional financial need based on the FAFSA Expected Family Contribution (EFC)", "Must be an undergraduate student who has not yet earned a bachelor''s degree", "Must be enrolled at least half-time at a participating college or university", "Must be a US citizen, eligible non-citizen, or qualifying non-citizen with valid Social Security number", "Cannot be in default on a federal student loan or owe an overpayment on a federal student aid grant"]'::jsonb,
  required_documents = '["Completed FAFSA (Free Application for Federal Student Aid) at studentaid.gov — file as early as October 1 for the upcoming year", "FSA ID (username and password) to access and sign the FAFSA online", "Social Security number (for you and your parents if dependent)", "Federal tax return and W-2s from 2 years prior (can use IRS Direct Data Exchange to transfer automatically)", "Records of untaxed income: child support, veterans benefits, worker''s comp, etc.", "Bank statements showing current balance of savings and checking accounts"]'::jsonb
WHERE slug IN ('federal-pell-grant', 'fseog-grant');

-- Fix FSEOG specifically (different from Pell)
UPDATE grants SET
  eligibility_criteria = '["Must have exceptional financial need as determined by the FAFSA — priority given to students with the lowest Expected Family Contribution (EFC = 0)", "Must be an undergraduate student enrolled at least half-time", "Must be a US citizen or eligible non-citizen", "FSEOG is awarded by the institution — not all schools participate, and funds are limited (apply as early as possible)", "Must also be eligible for the Federal Pell Grant (FSEOG supplements Pell for neediest students)"]'::jsonb,
  required_documents = '["FAFSA filed at studentaid.gov as early as possible (opens October 1)", "Financial aid award letter from your institution (FSEOG is packaged as part of your total aid offer)", "Enrollment verification confirming at least half-time status", "Contact your school''s financial aid office — FSEOG is awarded at the school level, not directly through the federal government"]'::jsonb
WHERE slug = 'fseog-grant';

