UPDATE grants SET
  eligibility_criteria = '["Household income must be at or below 50% of Area Median Income (priority for those at or below 30% AMI) for the county or metropolitan area", "Must be a US citizen or eligible non-citizen with qualifying immigration status", "Must not have violated any federal, state, or local anti-drug laws, or been evicted from public housing for drug-related activity within the last 3 years", "Must not currently owe money to any public housing authority", "Must pass criminal background check (rules vary by housing authority — violent crimes and certain drug offenses may disqualify)"]'::jsonb,
