WHERE slug IN ('housing-choice-voucher', 'hud-section-8-housing-choice-voucher');

UPDATE grants SET
  eligibility_criteria = '["Must be a state or local government, public housing authority, or nonprofit organization (individuals cannot apply directly)", "Project must provide affordable housing for low-income households (at or below 60% AMI for rental; 80% AMI for homeownership)", "Participating jurisdiction must have a current HUD-approved Consolidated Plan", "HOME funds must be matched by at least 25 cents of non-federal funds for every HOME dollar drawn", "Projects must comply with federal Davis-Bacon prevailing wage requirements for construction projects over $2,000"]'::jsonb,
  required_documents = '["HUD HOME application submitted by a Participating Jurisdiction (PJ) as part of the Annual Action Plan", "Individual homebuyers and renters apply through their local housing authority, nonprofit, or CHDO — not directly to HUD", "For individual applicants: income verification (tax returns, pay stubs), proof of residency, government-issued ID"]'::jsonb
