UPDATE grants SET
  eligibility_criteria = '["Must be a state or local government, or a private nonprofit organization", "Project must provide emergency shelter, transitional housing, or outreach/services to homeless individuals and families", "Grantee must match ESG funds with equal amounts of non-federal funds", "Programs must adhere to HMIS (Homeless Management Information System) data collection requirements", "Must implement a written standards for administering assistance (intake, eligibility, prioritization, termination)"]'::jsonb,
  required_documents = '["ESG application submitted to your state or local government HUD grantee (individuals cannot apply directly to HUD for ESG)", "For individuals seeking emergency shelter services: government-issued ID, documentation of homelessness or imminent risk, income verification (if required by local program)", "Organizations: HUD-approved Consolidated Plan, audited financials, organizational chart, HMIS participation agreement"]'::jsonb
