UPDATE grants SET
  eligibility_criteria = '["Must be a US citizen or qualified immigrant", "Must meet income requirements: for Medicaid expansion states, adults with income up to 138% FPL qualify; for traditional Medicaid, eligibility categories vary by state (families, pregnant women, elderly, disabled)", "Must reside in the state where you''re applying", "Must be a member of an eligibility category: children, pregnant women, families with children, individuals with disabilities, adults in expansion states, seniors 65+", "Asset limits vary by state and category — most states have eliminated asset tests for most populations"]'::jsonb,
  required_documents = '["Medicaid application at your state Medicaid agency, Healthcare.gov, or benefits.gov (online, phone, or in person)", "Government-issued photo ID", "Social Security card or SSN documentation for all household members", "Proof of income: pay stubs, W-2, Social Security award letter, or self-employment records", "Proof of US citizenship or immigration status (passport, birth certificate, green card, I-94)", "Proof of residency: utility bill, lease, or bank statement with current address"]'::jsonb
WHERE slug = 'medicaid';

