  eligibility_criteria = '["Must be an uninsured child under 19 years old", "Family income must be too high for Medicaid but unable to afford private insurance — typically between 100% and 200% FPL (some states cover up to 300% FPL or higher)", "Must be a US citizen, qualifying immigrant, or lawfully residing immigrant (rules vary by state)", "Must not be eligible for or covered by employer-sponsored health insurance", "Must be a resident of the state where you are applying"]'::jsonb,
