  required_documents = '["LIHEAP application at your state or local LIHEAP office (find at liheapch.acf.hhs.gov/profiles/states or call 211)", "Government-issued photo ID for the applicant", "Social Security cards or numbers for all household members", "Proof of all household income: pay stubs, Social Security award letters, unemployment statements (last 30 days)", "Most recent energy bill (electric, gas, or heating fuel) showing your account number and service address", "Proof of residency: lease, utility bill, or other official mail with your current address"]'::jsonb
