UPDATE grants SET
  eligibility_criteria = '["Must be a rural small business, agricultural producer, farmer, rancher, or rural cooperative", "Business must be located in an eligible rural area as defined by USDA (population <50,000)", "Must have a completed renewable energy system or energy efficiency improvement (for grants) or be planning one (for loan guarantees)", "Business must be operating and generating revenue", "Energy audit required for energy efficiency projects above $50,000", "Technical report required showing project feasibility and energy savings", "Must have matched funds — grant covers up to 25% of eligible project costs; loan guarantee up to 75%"]'::jsonb,
