UPDATE grants SET
  eligibility_criteria = '["Must be a state energy office designated by the governor", "Also eligible: the District of Columbia, US territories (Puerto Rico, Guam, US Virgin Islands, American Samoa, CNMI)", "Must have an approved State Energy Plan on file with DOE", "Must comply with Davis-Bacon prevailing wage requirements for construction projects", "Must meet DOE''s financial management and procurement standards (2 CFR Part 200)", "Subawards to local governments, nonprofits, and businesses are permitted under SEP"]'::jsonb,
  required_documents = '["SF-424 (Application for Federal Assistance) submitted via grants.gov", "State Energy Plan narrative and supporting data", "SF-424A Budget Information for Non-Construction Programs", "Assurances — Non-Construction Programs (SF-424B)", "CD-511 Certification Regarding Lobbying", "State organizational chart and key personnel resumes", "Indirect cost rate agreement (if applicable)"]'::jsonb
WHERE slug = 'doe-state-energy-program';

UPDATE grants SET
  eligibility_criteria = '["Must be a homeowner (not a renter) occupying the home as your primary residence", "Household income must be at or below 80% of Area Median Income for the full rebate; 80%–150% AMI for a 50% rebate", "Must hire a qualified contractor certified under the relevant DOE Home Energy Rebates program in your state", "Must install qualifying home energy upgrades: insulation, air sealing, heat pumps, heat pump water heaters, electric stoves, electric wiring upgrades, or weatherization", "Program is administered by states — check your state energy office for availability, as rollout varies by state", "Each home is eligible once per measure type (e.g., one insulation rebate, one heat pump rebate)"]'::jsonb,
  required_documents = '["Application submitted to your state energy office or designated program administrator (find at energy.gov/save)", "Contractor invoice showing qualifying work completed, cost breakdown, and contractor certification number", "Proof of household income: most recent federal tax return (Form 1040) or other income documentation", "Proof of homeownership and primary residency (deed, mortgage statement, or property tax bill)", "Before/after energy audit or assessment if required by your state program", "Equipment specification sheets showing qualifying efficiency ratings (ENERGY STAR or DOE criteria)"]'::jsonb
WHERE slug = 'ira-homes-rebate-program';

UPDATE grants SET
  eligibility_criteria = '["Must be a homeowner occupying the home as your primary residence", "Household income must be at or below 150% of Area Median Income (80%–150% AMI receives partial rebate; ≤80% AMI receives maximum rebate)", "Must purchase and install qualifying high-efficiency electric appliances or upgrades: heat pump HVAC, heat pump water heater, electric stove/range, electric clothes dryer, electrical panel upgrade, insulation/air sealing, or EV charger", "Must use a qualified contractor participating in your state''s HEEHRA program", "Program is state-administered — availability varies; check your state energy office", "Maximum household rebate is $14,000 total across all measures"]'::jsonb,
  required_documents = '["Application submitted to your state energy office or program administrator (find at energy.gov/save or call your utility)", "Proof of income: most recent federal tax return or W-2 (income eligibility verified at point of sale in most states)", "Proof of homeownership: mortgage statement, deed, or property tax bill", "Contractor invoice or receipt showing qualifying appliance/upgrade, cost, and installer certification", "Product specification sheet or model number for rebate verification", "Proof of primary residency at the property address"]'::jsonb
WHERE slug = 'ira-heehra-rebate-program';

UPDATE grants SET
  eligibility_criteria = '["Must be a local educational agency (school district), state educational agency, Indian tribe, or tribally operated school", "Must currently operate school buses used to transport students", "Buses being replaced must be diesel-powered and at least 10 years old (or meet other age criteria per program rules)", "Must demonstrate the ability to manage and complete the replacement project", "Priority given to applicants serving high-need areas, rural communities, and tribal nations", "Must commit to retiring (scrapping) replaced diesel buses — they cannot be resold or transferred"]'::jsonb,
  required_documents = '["EPA Clean School Bus application via grants.gov (SF-424 and program-specific forms)", "Fleet inventory listing current diesel buses: make, model, year, VIN, and engine type", "School district or tribal enrollment and transportation documentation", "Letters of support or MOUs with bus manufacturers or dealers if applicable", "Budget detail for purchase and installation of replacement vehicles or charging infrastructure", "Scrappage commitment certification", "SAM.gov registration (Unique Entity Identifier required for federal awards)"]'::jsonb
WHERE slug = 'epa-clean-school-bus-program';

UPDATE grants SET
  eligibility_criteria = '["Must be a state, territory, tribal nation, municipality, or eligible nonprofit organization", "Must propose to deploy solar energy in low-income and disadvantaged communities (as defined by DOE and EPA)", "Must demonstrate capacity to manage federal funds and execute solar deployment programs", "Program must include meaningful community engagement and benefit-sharing with low-income households", "Projects must result in savings on electricity bills for low-income participants", "Must comply with Davis-Bacon prevailing wage requirements and apprenticeship standards under IRA"]'::jsonb,
  required_documents = '["SF-424 (Application for Federal Assistance) submitted via grants.gov", "Program design narrative describing how solar will be deployed to low-income communities", "Community Benefits Plan describing engagement and benefit-sharing commitments", "Letters of support from community organizations and local partners", "Financial management plan demonstrating capacity to manage federal grant funds", "SF-424A Budget Information and budget narrative", "SAM.gov registration with active Unique Entity Identifier (UEI)"]'::jsonb
WHERE slug = 'doe-solar-for-all-program';

UPDATE grants SET
  eligibility_criteria = '["Must be an eligible entity: agricultural producer, farmer, rancher, rural small business, or farmer/rancher cooperative", "Projects must involve development or construction of a biorefinery, biobased product, or bioenergy facility", "Must be located in a rural area or produce agricultural commodities or forest products", "Commercially viable technology required — demonstration and commercial-scale projects are eligible", "Must provide non-federal matching funds (at least 20% match required)", "Must demonstrate technical and financial feasibility of the proposed project", "Technology must be beyond pilot scale — no basic research projects"]'::jsonb,
  required_documents = '["SF-424 (Application for Federal Assistance)", "Technical Proposal describing the biobased technology, production process, and commercial viability", "Business plan with financial projections (3-5 years)", "Environmental information document", "Proof of matching funds: commitment letters, bank statements, or equity documentation", "Engineering or feasibility study prepared by a qualified professional", "Documentation of feedstock source and supply agreements if applicable", "DUNS number / SAM.gov Unique Entity Identifier registration"]'::jsonb
