UPDATE grants SET
  eligibility_criteria = '["Must be a unit of local government, state government, or tribal government", "Must have an Energy Efficiency and Conservation Strategy (EECS) on file with DOE", "Local governments serving populations under 35,000 receive formula-based allocations; larger entities receive direct DOE awards", "Must use funds for eligible activities: building retrofits, transportation improvements, renewable energy installation, energy audits, lighting upgrades, or community energy planning", "Must comply with Davis-Bacon prevailing wage requirements for construction-related activities", "Must demonstrate financial capacity and ability to manage federal grant funds"]'::jsonb,
  required_documents = '["SF-424 (Application for Federal Assistance) submitted via grants.gov or through state for smaller jurisdictions", "Energy Efficiency and Conservation Strategy narrative", "SF-424A Budget Information and detailed budget justification", "Community energy use data and baseline assessment", "Certification regarding lobbying (CD-511)", "SAM.gov registration with Unique Entity Identifier", "Environmental review documentation per National Environmental Policy Act (NEPA)"]'::jsonb
