UPDATE grants SET
  eligibility_criteria = '["Must be a US-based for-profit small business with fewer than 500 employees (SBC — Small Business Concern per SBA standards)", "Must be at least 51% owned and controlled by US citizens or permanent residents", "Principal Investigator (PI) must have a primary employment relationship with the applicant SBC (at least 51% effort)", "Research must address a health topic relevant to NIH''s mission and the specific NIH institute''s priorities", "Must be in Phase I (feasibility) — prior Phase I award in the same topic required for Phase II application", "Must register in SAM.gov and NIH eRA Commons before applying"]'::jsonb,
  required_documents = '["SF-424 R&R (Application for Federal Assistance — Research and Related) submitted via grants.gov", "PHS 398 Research Plan: Specific Aims, Research Strategy (6 pages Phase I, 12 pages Phase II)", "Small Business Certification (SBC) — online in eRA Commons", "Commercialization Plan (required for Phase II)", "NIH Biosketch for all senior/key personnel (2-page format)", "Budget justification using SF-424A or R&R Budget", "Letters of support from commercial partners or licensees if applicable", "Human subjects or vertebrate animals documentation if applicable", "Facilities and Other Resources document"]'::jsonb
WHERE slug = 'nih-sbir-health';

UPDATE grants SET
  eligibility_criteria = '["Must be a public or nonprofit private entity (including tribal organizations and faith-based organizations)", "Must serve a Medically Underserved Area (MUA) or Medically Underserved Population (MUP) as designated by HRSA", "Must provide comprehensive primary health care services regardless of patients'' ability to pay", "Must operate under the governance of a community board where at least 51% of members are health center patients", "Must provide enabling services (translation, transportation, case management)", "Must comply with all Section 330 program requirements under the Public Health Service Act"]'::jsonb,
  required_documents = '["HRSA Electronic Handbook (EHB) application — submitted online via grants.hrsa.gov", "Project Narrative (Health Center Program application forms)", "Forms 5A–5C: Service Sites, Service Area, Staffing", "Form 6A: Current Board Member Characteristics", "Form 2: Impacted Special Populations", "SF-424 (Application for Federal Assistance)", "Audited financial statements or financial review (most recent fiscal year)", "IRS tax-exempt status determination letter (Form 1023/1024 approval)", "Board bylaws and governance documents"]'::jsonb
WHERE slug = 'hrsa-federally-qualified-health-center-grant';

UPDATE grants SET
  eligibility_criteria = '["Must be a state or local health department, community-based organization, academic institution, or tribal organization", "Must serve communities with documented community health worker (CHW) workforce gaps or training needs", "Must propose evidence-based or evidence-informed CHW training curriculum", "Organization must have demonstrated experience in community health or workforce development", "Must include a plan for sustainability of CHW workforce after grant period", "Priority given to organizations serving rural, underserved, or tribal communities"]'::jsonb,
  required_documents = '["SF-424 (Application for Federal Assistance) submitted via grants.gov", "Project Narrative describing CHW training model, curriculum, and evaluation plan", "Organizational capability statement and key staff bios/CVs", "Letters of support from community partners and employers of CHWs", "SF-424A Budget Information and budget justification", "Logic model or program framework showing inputs, activities, outputs, and outcomes", "Any existing CHW curriculum or training materials (as appendix)"]'::jsonb
WHERE slug = 'cdc-community-health-worker-training-grant';

UPDATE grants SET
  eligibility_criteria = '["Must be a state substance abuse agency (SSA) designated by the governor — this is a formula block grant to states only, not available to nonprofits or local governments directly", "State must submit an annual application and State Plan to SAMHSA", "Funds must be used for prevention, treatment, and recovery support services for substance use disorders", "Must maintain a statewide substance abuse management information system", "State must conduct a statewide needs assessment every 3 years", "Must set aside 20% of funds for primary prevention programs targeting non-substance-using populations"]'::jsonb,
  required_documents = '["Annual Block Grant Application submitted via SAMHSA''s Behavioral Health Assessment and Performance Tool (BHART) or SPARS system", "State Plan for substance abuse prevention and treatment services", "Statewide Needs Assessment (updated every 3 years)", "SF-424 (Application for Federal Assistance)", "Certifications and assurances required by SAMHSA", "Prior year expenditure and performance data report"]'::jsonb
WHERE slug = 'samhsa-substance-abuse-prevention-treatment-grant';

UPDATE grants SET
  eligibility_criteria = '["Must hold a PhD, MD, DO, or equivalent research doctorate in a cancer-related field", "Must have an institutional affiliation (university, research institute, hospital) that can receive and administer grant funds", "Research must address breast cancer — basic, translational, or clinical research", "Independent investigators must submit through their institution''s sponsored programs office", "Must comply with Komen''s Conflict of Interest and Human Subjects policies", "Research involving human subjects requires IRB approval documentation", "Specific award mechanisms (e.g., Career Catalyst, Investigator Initiated) have additional eligibility criteria — check Komen''s grant portal"]'::jsonb,
  required_documents = '["Komen Online Grants Management System (OGMS) application — submitted at komengrants.org", "Research Project Narrative and Specific Aims (page limit varies by mechanism)", "NIH-format Biosketch for PI and all co-investigators", "IRB approval or exemption documentation for human subjects research", "Budget and budget justification", "Institutional sign-off from sponsored programs office (Authorized Organizational Representative)", "Letters of support from collaborators and department chair", "References list and bibliography"]'::jsonb
WHERE slug = 'susan-g-komen-breast-cancer-research-grant';

UPDATE grants SET
  eligibility_criteria = '["Must be an early-career faculty member — typically within 10 years of completing postdoctoral training or equivalent research experience", "Must hold an MD, PhD, DO, or equivalent terminal degree", "Must have a full-time faculty appointment (assistant professor or equivalent) at a US or Canadian academic or research institution", "Must not be a Principal Investigator on an NIH R01 or equivalent independent research award at the time of application", "Research must be in areas relevant to the American Heart Association''s scientific focus: cardiovascular disease, stroke, and related conditions", "Must be an AHA Professional Member (membership can be established at time of application)"]'::jsonb,
  required_documents = '["AHA Online Grant Application via professional.heart.org", "Project Narrative: Specific Aims, Research Plan (Innovation, Approach), Background (page limits apply)", "NIH-format Biosketch for PI and all co-investigators", "Mentor letter if applicable (some mechanisms require mentorship component)", "Institutional letter from department chair confirming protected research time and support", "Budget and budget justification", "Letters of collaboration from co-investigators", "Human subjects or IACUC animal protocol approval if applicable"]'::jsonb
WHERE slug = 'american-heart-association-innovative-project-award';

UPDATE grants SET
  eligibility_criteria = '["Must be a mid-career professional in health, medicine, nursing, dentistry, social work, public health, or a health-related behavioral or social science", "Must have a doctoral degree (MD, PhD, DrPH, JD, or equivalent) or a clinical or professional health degree", "Must be a US citizen or permanent resident", "Must have at least 5 years of professional experience in health or health policy after completing training", "Must currently work in health care delivery, health research, public health practice, or a related health field", "Fellowship year is spent in Washington, DC working with Congressional or executive branch offices — applicants must be willing to relocate", "Must not be a current employee of the federal government at time of application"]'::jsonb,
  required_documents = '["RWJF online application portal at rwjf.org/hpf", "Curriculum vitae (CV) with full work and publication history", "Personal statement explaining interest in health policy and how the fellowship will advance your career goals", "Three letters of recommendation from colleagues, supervisors, or academic advisors", "Official transcripts from highest degree granting institution", "Writing sample demonstrating policy analysis or health research (10-15 pages)"]'::jsonb
