UPDATE grants SET
  eligibility_criteria = '["Must be a US-based 501(c)(3) nonprofit organization (foundation, public charity) or a federally recognized tribal nation", "Must align with Kellogg Foundation''s focus areas: thriving children, working families, and equitable communities", "Priority given to organizations working to advance racial equity and healing", "Must operate in Kellogg''s geographic priority areas or national/regional initiatives (Michigan, Mississippi, New Mexico, New Orleans, and other areas)", "Unsolicited proposals are generally not accepted — Kellogg initiates most grants through invitations or RFPs", "Organizations must submit a Letter of Inquiry (LOI) first; full proposals by invitation only"]'::jsonb,
  required_documents = '["Letter of Inquiry (LOI) submitted via Kellogg Foundation''s online grants portal at wkkf.smapply.org", "IRS 501(c)(3) tax-exempt determination letter", "Most recent audited financial statements (last 2 fiscal years)", "Organizational budget for current fiscal year", "List of current board members", "Most recent annual report (if available)", "If invited to submit full proposal: project narrative, logic model, evaluation plan, and detailed budget"]'::jsonb
