UPDATE grants SET
  eligibility_criteria = '["Must be a state or local public health agency, academic institution, research organization, or community-based organization", "Must serve or conduct research relevant to rural populations and rural health challenges", "Must demonstrate understanding of rural health disparities, access barriers, and workforce shortages", "Organization must be located in or demonstrate strong ties to rural communities to be served", "Must show evidence-based approach to proposed rural health program or research", "Priority given to projects with strong community partnership components"]'::jsonb,
