UPDATE grants SET
  eligibility_criteria = '["Must be a state maternal and child health agency (Title V agency) designated by the governor — this is a formula block grant to states and territories only", "Must submit an annual application and State MCH Plan to HRSA", "Must conduct a statewide 5-year needs assessment focusing on MCH populations", "Funds must serve pregnant women, mothers, infants, children (including those with special healthcare needs), and families", "States must set aside 30% of funds for children with special health care needs (CSHCN)", "Must maintain data systems for MCH performance measurement and reporting to HRSA"]'::jsonb,
